from fastapi.sse import ServerSentEvent
from pydantic import ValidationError

def test_sse_validation():
    # Test valid event
    try:
        ServerSentEvent(event="test-event", id="123", data="hello")
        print("Valid event passed")
    except ValidationError as e:
        print(f"Valid event failed: {e}")

    # Test invalid event (newline)
    try:
        ServerSentEvent(event="test\nevent", id="123", data="hello")
        print("Invalid event (newline) failed to raise error")
    except ValidationError as e:
        print(f"Invalid event (newline) raised error: {e}")

    # Test invalid event (carriage return)
    try:
        ServerSentEvent(event="test\revent", id="123", data="hello")
        print("Invalid event (carriage return) failed to raise error")
    except ValidationError as e:
        print(f"Invalid event (carriage return) raised error: {e}")

    # Test invalid id (newline)
    try:
        ServerSentEvent(event="test-event", id="123\n456", data="hello")
        print("Invalid id (newline) failed to raise error")
    except ValidationError as e:
        print(f"Invalid id (newline) raised error: {e}")

    # Test invalid id (carriage return)
    try:
        ServerSentEvent(event="test-event", id="123\r456", data="hello")
        print("Invalid id (carriage return) failed to raise error")
    except ValidationError as e:
        print(f"Invalid id (carriage return) raised error: {e}")

    # Test invalid id (null character)
    try:
        ServerSentEvent(event="test-event", id="123\0456", data="hello")
        print("Invalid id (null) failed to raise error")
    except ValidationError as e:
        print(f"Invalid id (null) raised error: {e}")

if __name__ == "__main__":
    test_sse_validation()

